use std::{collections::BTreeMap, time::Instant};
use gwt::{IssueMonitorIssue, IssueMonitorIssueState, IssueMonitorReadiness};
use gwt::cli::LinkedPrSummary;
use gwt::issue_monitor_worker::LinkedPrProbeBatch;

fn issue(number: u64) -> IssueMonitorIssue {
    IssueMonitorIssue {
        number, author_login: None, title: format!("SPEC {number}"),
        labels: vec!["gwt-spec".into()], state: IssueMonitorIssueState::Open,
        body: None, url: None, readiness: IssueMonitorReadiness::ReadyWithCompletedTasks,
        updated_at: Some("2026-09-01T00:00:00Z".into()),
    }
}

fn sample(seed: &BTreeMap<u64, Vec<LinkedPrSummary>>, rows: &BTreeMap<u64, Vec<LinkedPrSummary>>) -> (f64, u64) {
    let issues = [issue(1), issue(2)];
    let mut calls = 0;
    let start = Instant::now();
    for _ in 0..1000 {
        let batch = LinkedPrProbeBatch::prefetch_with(&[1, 2], seed, |numbers| {
            calls += 1;
            assert_eq!(numbers, [1, 2]);
            Ok(rows.clone())
        });
        assert_eq!(batch.len(), 2);
        assert_eq!(batch.completed(&issues[0]), Some(true));
        assert_eq!(batch.completed(&issues[1]), Some(false));
        assert!(batch.failure().is_none());
        std::hint::black_box(batch);
    }
    (start.elapsed().as_secs_f64() * 1000.0, calls)
}

fn main() {
    let rows = BTreeMap::from([
        (1, vec![LinkedPrSummary { number: 101, title: "fix #1".into(),
            state: "MERGED".into(), url: String::new(), will_close_target: true,
            merged_at: Some("2026-09-02T00:00:00Z".into()) }]),
        (2, Vec::new()),
    ]);
    let empty = BTreeMap::new();
    let _ = sample(&empty, &rows);
    let _ = sample(&rows, &rows);
    for round in 0..12 {
        let (before, after) = if round % 2 == 0 {
            (sample(&empty, &rows), sample(&rows, &rows))
        } else {
            let after = sample(&rows, &rows);
            (sample(&empty, &rows), after)
        };
        println!("{{\"round\":{round},\"control_ms\":{},\"reused_ms\":{},\"control_fetches\":{},\"reused_fetches\":{}}}", before.0, after.0, before.1, after.1);
    }
}

